CREATE FUNCTION public.checkout_guest_cart(_items jsonb,_name text,_phone text,_address text,_notes text,_request_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid; BEGIN IF NOT public.is_account_active() THEN RAISE EXCEPTION 'Unauthorized'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); SELECT id INTO oid FROM public.orders WHERE id=_request_id AND user_id=auth.uid(); IF oid IS NOT NULL THEN RETURN oid; END IF; PERFORM public.merge_guest_cart(_items); RETURN public.checkout_cart(_name,_phone,_address,_notes,_request_id); END $$;
REVOKE ALL ON FUNCTION public.checkout_guest_cart(jsonb,text,text,text,text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.checkout_guest_cart(jsonb,text,text,text,text,uuid) TO authenticated;